-- Day 2: turn separate cards about roles into one connected story about a task.

do $$
declare
  day_two_id uuid;
begin
  select id into day_two_id from public.lessons where day_number = 2;

  if day_two_id is null then
    raise exception 'Lesson for day 2 was not found';
  end if;

  -- The structure and required checkpoints have changed, so old Day 2 progress
  -- must not make the new material appear as already completed.
  delete from public.lesson_block_progress
  where lesson_id = day_two_id;

  delete from public.lesson_progress
  where lesson_id = day_two_id;

  delete from public.lesson_blocks
  where lesson_id = day_two_id;

  insert into public.lesson_blocks (lesson_id, block_type, position, content) values
    (day_two_id, 'heading', 0, '{"title":"Как работает IT-команда","eyebrow":"День 2 из 14"}'::jsonb),
    (day_two_id, 'text', 1, $json$
      {"markdown":"В первом уроке ты узнал, что QA помогает команде замечать риски и понимать качество продукта. Но QA не работает в одиночку. Каждая функция проходит через несколько людей, и результат зависит от того, насколько хорошо они понимают друг друга.\n\nПредставим небольшую задачу. В сервисе доставки пользователь должен получать письмо, когда заказ передан курьеру. По этой задаче легко увидеть, зачем в команде нужны разные специалисты и где QA может помочь."}
    $json$::jsonb),
    (day_two_id, 'definition', 2, '{"term":"Кросс-функциональная команда","text":"Это команда специалистов разных направлений, которые вместе создают и улучшают продукт."}'::jsonb),

    (day_two_id, 'heading', 3, '{"title":"Одна задача, разные роли","startsStep":true}'::jsonb),
    (day_two_id, 'text', 4, $json$
      {"markdown":"Сначала Product Manager или Product Owner формулирует, какую пользу должна дать функция. В нашем случае пользователь должен вовремя узнать, что заказ уже в пути.\n\nАналитик помогает превратить цель в понятные правила. Дизайнер продумывает путь пользователя и текст письма. Разработчик создаёт функцию. QA уточняет, можно ли её проверить, и замечает риски до и после разработки. На практике границы ролей могут отличаться, но задача остаётся общей."}
    $json$::jsonb),
    (day_two_id, 'diagram', 5, '{"title":"Как движется задача","steps":["Цель: пользователь узнаёт, что заказ передан курьеру","Правила: когда отправлять письмо и что в нём написать","Дизайн: как выглядит письмо и ссылка на заказ","Разработка: функция отправляет письмо","Проверка: команда сверяет результат с правилами","Релиз и обратная связь от пользователей"]}'::jsonb),
    (day_two_id, 'question', 6, '{"question":"Кто обычно отвечает за то, чтобы цель задачи и её приоритет были понятны команде?","options":["Product Manager или Product Owner","Только QA","Только дизайнер","Пользователь после релиза"],"correctIndex":0,"explanation":"Product Manager или Product Owner формулирует цель и помогает расставить приоритеты. Остальные специалисты уточняют и реализуют решение вместе с ним.","blocksNext":true}'::jsonb),

    (day_two_id, 'heading', 7, '{"title":"Почему QA подключается ещё до готовой функции","startsStep":true}'::jsonb),
    (day_two_id, 'text', 8, $json$
      {"markdown":"Вернёмся к письму о доставке. В задаче может быть написано только «отправлять уведомление, когда заказ передан курьеру». Этого недостаточно для разработки и проверки. Неясно, кому придёт письмо, что будет при отмене заказа и что увидит пользователь, если отправка не удалась.\n\nQA не обязан сам придумывать бизнес-правило. Его задача заметить пробел, задать вопрос и помочь команде договориться. После этого у разработки появляется понятное условие, а у QA — проверяемое ожидание."}
    $json$::jsonb),
    (day_two_id, 'example', 9, '{"title":"Уточняем правило до разработки","expected":"Команда договорилась: письмо получает владелец заказа сразу после передачи заказа курьеру. При отмене письмо не отправляется.","actual":"В исходной задаче не сказано, что делать при отмене и кому отправлять письмо, если заказ оформлен для другого человека.","conclusion":"QA задаёт вопросы до разработки. Так команда уменьшает риск разной трактовки правила и лишней переделки."}'::jsonb),
    (day_two_id, 'important', 10, '{"title":"QA не принимает решения за бизнес","text":"QA помогает сделать правила ясными и проверяемыми. Окончательное бизнес-решение принимает тот, кто отвечает за продукт."}'::jsonb),
    (day_two_id, 'question', 11, '{"question":"Какие действия QA уместны, если правило в задаче неполное?","options":["Задать вопрос и зафиксировать договорённость","Самостоятельно выбрать правило и считать его единственно верным","Попросить разработчика угадать нужное поведение","Подумать, какие ситуации важно уточнить"],"questionType":"multiple_choice","correctAnswers":[0,3],"explanation":"QA замечает неясность, задаёт вопросы и помогает сделать ожидания проверяемыми. Решение о правиле остаётся за теми, кто отвечает за продукт.","blocksNext":true}'::jsonb),

    (day_two_id, 'heading', 12, '{"title":"После разработки задача не заканчивается","startsStep":true}'::jsonb),
    (day_two_id, 'text', 13, $json$
      {"markdown":"Когда функция готова, QA проверяет согласованные сценарии. Например, письмо приходит владельцу заказа после передачи курьеру, содержит номер заказа и ведёт на нужный экран. Затем команда смотрит на найденные проблемы, исправляет их при необходимости и выпускает изменение.\n\nПосле релиза работа тоже продолжается. Поддержка, аналитика и обратная связь пользователей могут показать, что сценарий нужно улучшить. Поэтому качество не принадлежит одному человеку. За него отвечает вся команда."}
    $json$::jsonb),
    (day_two_id, 'definition', 14, '{"term":"QA Engineer","text":"Специалист, который помогает команде предотвращать проблемы с качеством, выбирать проверки и сообщать о результатах и рисках."}'::jsonb),
    (day_two_id, 'diagram', 15, '{"title":"Как роли помогают одной задаче","steps":["Product Manager или Product Owner объясняет цель","Аналитик уточняет правила и ограничения","Дизайнер делает сценарий понятным пользователю","Разработчик реализует решение","QA проверяет ожидания и сообщает о рисках","Команда вместе решает, что улучшить"]}'::jsonb),
    (day_two_id, 'question', 16, '{"question":"Функция готова, но письмо ведёт не на страницу заказа, а на главную. Какой следующий шаг разработчика наиболее уместен?","options":["Исправить согласованное поведение после понятного описания проблемы","Самостоятельно изменить цель задачи","Удалить письмо из функции","Считать проверку ненужной"],"correctIndex":0,"explanation":"QA передаёт наблюдение с условиями и ожидаемым результатом. Разработчик исправляет согласованное решение, а команда при необходимости уточняет детали.","blocksNext":true}'::jsonb),

    (day_two_id, 'summary', 17, '{"title":"Главное из урока","items":[["Кросс-функциональная команда","Специалисты разных направлений вместе создают и улучшают продукт."],["Цель задачи","Понятный ответ на вопрос, какую пользу функция должна дать пользователю и продукту."],["QA Engineer","Помогает сделать правила проверяемыми, выбирает проверки и сообщает о рисках."]],"points":["Задача движется от цели и правил к разработке, проверке и обратной связи.","QA подключается до разработки, чтобы замечать неполные или противоречивые условия.","Качество зависит от совместной работы всей команды, а не только от проверки готовой функции."]}'::jsonb),
    (day_two_id, 'question', 18, '{"question":"Какие утверждения о работе команды верны?","options":["QA может уточнять неясные условия до разработки","Качество зависит только от QA","У каждой роли есть своя зона ответственности, но задача общая","После релиза обратная связь уже не нужна"],"questionType":"multiple_choice","correctAnswers":[0,2],"explanation":"QA помогает сделать требования яснее, а задача проходит через общую работу специалистов. Обратная связь после релиза помогает понять, что улучшить дальше.","blocksNext":true}'::jsonb);
end;
$$;
